    if (filename == null) {
        return -1;
    }
    int extensionPos = filename.lastIndexOf('.');
    int lastSeparatorPos = indexOfLastSeparator(filename);
    if (extensionPos == -1 || lastSeparatorPos > extensionPos) {
        return -1;
    }
    return extensionPos;
}

