public void generateGraph(Graph<V,E> target, Map<String,V> resultMap){
    int numVertices = resultMap.size();
    if (numVertices % 2 != 0) {
        throw new IllegalArgumentException("Number of vertices must be even for a complete bipartite graph.");
    }
    int n1 = numVertices / 2;
    int n2 = numVertices / 2;
    Set<V> set1 = new HashSet<>();
    Set<V> set2 = new HashSet<>();
    int i = 0;
    for (V vertex : resultMap.values()) {
        if (i < n1) {
            set1.add(vertex);
        } else {
            set2.add(vertex);
        }
        i++;
    }
    for (V vertex1 : set1) {
        for (V vertex2 : set2) {
            target.addEdge(vertex1, vertex2);
        }
    }
}

