        throw new IllegalArgumentException("Number of vertices must be even for complete bipartite graph");
    }
    Set<V> part1 = new HashSet<>(vertices);
    Set<V> part2 = new HashSet<>(vertices);
    part1.retainAll(vertices);
    part2.removeAll(part1);

    for (V v1 : part1) {
        for (V v2 : part2) {
            target.addEdge(new Edge<>(v1, v2));
        }
    }
}

