protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Input set and graph must not be null");
    }

    List<E> edgeList = new ArrayList<>(tour);
    V startVertex = null;
    V endVertex = null;

    // Find the start and end vertices
    for (E edge : edgeList) {
        if (startVertex == null) {
            startVertex = graph.getEdgeSource(edge);
        }
        endVertex = graph.getEdgeTarget(edge);
    }

    if (!tour.contains(graph.getEdge(startVertex, endVertex))) {
        throw new IllegalArgumentException("Tour must form a closed path");
    }

    return graph.getPath(startVertex, endVertex);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<Edge<V,E>> edges = new ArrayList<>(tour);
    if (edges.isEmpty()) {
        return graph.createEmptyGraphPath();
    }

    V start = edges.get(0).getTarget();
    V end = start;
    for (Edge<V,E> edge : edges) {
        end = edge.getTarget();
    }

    return graph.createPath(start, end, tour);
}

