    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String path = u.getPath();
    if (path == null) {
        return pathSegments;
    }
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    if (!decode) {
        pathSegments.add(new PathSegmentImpl(path, null));
        return pathSegments;
    }
    String[] segments = path.split("/");
    for (String segment : segments) {
        try {
            pathSegments.add(new PathSegmentImpl(URLDecoder.decode(segment, "UTF-8"), null));
