                }
            } else if (i % 2 == 0 && i != 8) {
                if (day > 30) day = 30;
            } else {
                if (day > 31) day = 31;
            }
            if (day != 0) break;
            day += 31;
            month--;
        }
    }

    return year * 10000L + month * 100 + day;
}

